    [Theory]
    [MemberData(nameof(OriginalCases))]
    public void Actual_original_thin_ice_matches_all_retained_tiles_rng_and_ordered_structures(int seed,int profile,bool returned,string grid,string rng)
    {
        var workspace=new Workspace(180,220);workspace.InitializeVanillaStructureMap();
        for(int x=0;x<180;x++)for(int y=0;y<220;y++)
        {
            int key=(x*13+y*7)%31;ushort type=profile switch {0=>147,1=>0,2=>59,3=>225,4=>(ushort)(key<16?147:1),5=>(ushort)(key<16?147:59),_ => (ushort)(((x*31+y*13)%17) switch{0=>161,1=>224,2=>0,3=>1,_=>147})};
            if(profile>=6&&x>82&&x<98&&y>83&&y<99)type=(ushort)(key%4 switch{0=>21,1=>467,2=>226,_=>237});
            var tile=new WorldTile{Type=type,Wall=15,FrameX=18,FrameY=36,TileColor=7,WallColor=9,LiquidAmount=(byte)(profile>=6?key*8:0),LiquidKind=(WorldLiquidKind)(profile%4),Flags=WorldTileFlagMasks.Visibility|WorldTileFlagMasks.Fullbright};
            if(profile<7||key%3!=0)tile.Flags|=WorldTileFlags.Active;
            if((key&1)!=0)tile.Flags|=WorldTileFlags.WireRed;if((key&2)!=0)tile.Flags|=WorldTileFlags.WireBlue;if((key&4)!=0)tile.Flags|=WorldTileFlags.WireGreen;if((key&8)!=0)tile.Flags|=WorldTileFlags.WireYellow;if((key&16)!=0)tile.Flags|=WorldTileFlags.Actuator;if(profile>=8&&key%5==0)tile.Flags|=WorldTileFlags.Inactive;
            tile.TrySetSourceShape(profile>=9&&key%5==0,(byte)(profile>=10?key%5:0));workspace.TileStore.Set(x,y,tile);
        }
        var random=new IceRandom(seed);
        Assert.Equal(returned,ThinIceBiome1458.Place(workspace,random,90,90));
        using var bytes=new MemoryStream();using(var writer=new BinaryWriter(bytes))
            for(int x=0;x<180;x++)for(int y=0;y<220;y++){var tile=workspace.TileStore.Get(x,y);writer.Write(tile.Type);writer.Write(tile.Wall);writer.Write(tile.FrameX);writer.Write(tile.FrameY);writer.Write(tile.LiquidAmount);writer.Write((byte)tile.LiquidKind);writer.Write(tile.Shape);writer.Write(tile.TileColor);writer.Write(tile.WallColor);writer.Write((ushort)tile.Flags);}
        Assert.Equal(grid,Convert.ToHexString(SHA256.HashData(bytes.ToArray())));
        using var state=new MemoryStream();using(var writer=new BinaryWriter(state)){writer.Write((uint)typeof(VanillaUnifiedRandom1458).GetField("inext",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(random.Source)!);foreach(int value in (int[])typeof(VanillaUnifiedRandom1458).GetField("seedArray",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(random.Source)!)writer.Write(value);}
        Assert.Equal(rng,Convert.ToHexString(SHA256.HashData(state.ToArray())));
        Assert.Equal(returned?new[]{new WorldTileRegion(57,57,66,66)}:[],workspace.VanillaStructureMap.CaptureStructures());
        Assert.Empty(workspace.VanillaStructureMap.CaptureProtectedStructures());
    }
    private sealed class IceRandom(int seed):IWorldGenerationVanillaRandom
    {
        internal readonly VanillaUnifiedRandom1458 Source=new(seed);
        public int Next()=>Source.Next();public int Next(int max)=>Source.Next(max);public int Next(int min,int max)=>Source.Next(min,max);public double NextDouble()=>Source.NextDouble();public void NextBytes(byte[] bytes)=>Source.NextBytes(bytes);
    }
